// Map the selected catalog_lines (sent by the app in the webhook body) to the Hermes item
// shape and hand them over as ONE payload — one request for the whole selection, the way
// it worked before f03db96 (client, 2026-07-31).
//
// Returning a SINGLE n8n item is what makes the HTTP node fire exactly once: n8n runs an
// HTTP node once per input item, so one item in = one POST out.
//
// EAN: the catalog stores a 13-digit EAN, but Hermes wants the barcode WITHOUT the
// catalog's leading zero — a 13-digit EAN starting with 0 is sent as 12 digits
// (0075678581519 -> 075678581519). Only the first zero is dropped; a non-zero 13-digit EAN
// or an already-12-digit one is sent unchanged (Hermes accepts 12 or 13).
const hermesEan = (v) => {
  const s = String(v ?? '').replace(/[^0-9]/g, '');
  if (!s) return null;
  return (s.length === 13 && s[0] === '0') ? s.slice(1) : s;
};

const lines = $('Webhook').first().json.body?.lines ?? [];

return [{ json: {
  items: lines.map(l => ({
    title: l.title ?? null,
    author: l.artist ?? null,
    releaseDate: l.release_date ?? null,
    format: l.format ?? null,
    ean: hermesEan(l.ean),
    calculationGroup: l.calculation_group ?? null,
    supplierCode: l.supplier_code ?? null,
  })),
  // Carried alongside the payload so Map Sent can tie a response row back to a catalog
  // line. Kept in the SAME ORDER as items.
  meta: lines.map(l => ({ line_id: l.id, ean: l.ean ?? null })),
} }];

// Map Sent — write Hermes' item CODE back into Supabase as hermes_id, and mark as sent
// only the lines Hermes confirmed.
//
// WHAT CHANGED (Jože, 2026-07-31): the value the response had always carried was Hermes'
// INTERNAL row id, not the item code — which is why it was often 0 and never matched
// anything Nika could look up. He has added a separate `Code` field holding the actual
// item code, and that is what belongs in hermes_id. The internal id keeps one job here:
// its presence still proves the row was processed, even though its value is not stored.
//
// Response (one object per request, n8n may surface it several ways):
//   { message, return_description, return_value, status }
//   * status 1 -> processed. return_value is a JSON *string* array, expected to be
//                 [{ EAN: '075678581540', MblaID: 70463, Code: '...' }, ...].
//                 The exact spelling of the code field was not supplied, so every
//                 plausible one is accepted rather than guessing a single name.
//   * status 0 -> something was skipped. return_value is pipe-delimited text naming the
//                 EANs ("Item with EAN = ... already exists ... Skipping insertion.").
//                 Jože confirmed the run CONTINUES past such an error and still processes
//                 the remaining items, so status 0 no longer implies the batch was lost.
//
// The confirmation check below is a regression net, not an expected path: a line is marked
// sent only when Hermes accounted for it. Its only possible failure mode is leaving a line
// UNSENT and visible in the app — never marking one sent that was not.

// 1) Gather the response object(s) however n8n surfaced the top-level array.
const responses = [];
for (const it of $('Hermes POST Catalogue').all()) {
  const j = it.json;
  if (Array.isArray(j)) responses.push(...j);
  else if (j && Array.isArray(j.body)) responses.push(...j.body);
  else if (j) responses.push(j);
}

const normEan = v => String(v ?? '').replace(/[^0-9]/g, '').replace(/^0+/, '');
// An identifier of nothing-but-zeros is not an identifier (the old MblaID 0 case).
const cleanId = v => {
  const s = String(v ?? '').trim();
  return (!s || /^0+$/.test(s)) ? null : s;
};
// Hermes' own spelling of the code field was not supplied with the change; take whichever
// of these it turns out to use. ID/MblaID are deliberately NOT in this list — that is the
// internal row id and must never land in hermes_id again.
const codeOf = row => cleanId(
  row.Code ?? row.code ?? row.ItemCode ?? row.itemCode ?? row.item_code ??
  row.ProductCode ?? row.productCode ?? row.Sifra ?? row.sifra
);

const codeByEan = new Map();   // EAN -> item code
const confirmed = new Set();   // EANs Hermes accounted for at all
let requestProcessed = false;  // any response with status 1

for (const r of responses) {
  if (!r) continue;
  if (Number(r.status) === 1) requestProcessed = true;

  let rv = r.return_value;
  if (rv == null) continue;

  if (typeof rv === 'string') {
    const s = rv.trim();
    if (s.startsWith('[') || s.startsWith('{')) {
      try { rv = JSON.parse(s); } catch (e) { continue; }
    } else {
      // Plain text: it names the EANs it skipped because they already exist. Those rows
      // ARE in Hermes, so they count as confirmed — they just bring no code.
      for (const hit of (s.match(/EAN\s*=?\s*'?\d{8,14}/gi) || [])) {
        const d = hit.match(/\d{8,14}/);
        if (d) confirmed.add(normEan(d[0]));
      }
      continue;
    }
  }

  for (const row of (Array.isArray(rv) ? rv : [rv])) {
    if (!row) continue;
    const ean = row.EAN ?? row.ean;
    if (ean == null) continue;
    const key = normEan(ean);
    confirmed.add(key);                       // present in the response = accounted for
    const code = codeOf(row);
    if (code != null) codeByEan.set(key, code);
  }
}

// 2) Current hermes_id per line, straight from the webhook payload (select *), so a value
//    a row already had is never clobbered. Nothing-but-zeros is treated as absent: rows
//    written before this rule carry '0' from the old internal-id behaviour.
const existingById = new Map(
  ($('Webhook').first().json.body?.lines ?? []).map(l => [String(l.id), cleanId(l.hermes_id)])
);

// 3) One writeback row per CONFIRMED line.
const meta = $('Prepare Items').first().json.meta ?? [];
const out = [];
const unconfirmed = [];
for (const m of meta) {
  const key = normEan(m.ean);
  if (!confirmed.has(key) && !requestProcessed) { unconfirmed.push(m.ean || m.line_id); continue; }
  out.push({ json: {
    id: m.line_id,
    hermes_id: codeByEan.get(key) ?? existingById.get(String(m.line_id)) ?? null,
  } });
}

if (unconfirmed.length) {
  console.log('Hermes did not account for ' + unconfirmed.length + ' of ' + meta.length +
    ' line(s); they stay unsent and can be re-sent: ' + unconfirmed.join(', '));
}

// Nothing confirmed at all -> fail loudly rather than answer the app with a silent success.
if (!out.length) {
  const r = responses[0] || {};
  throw new Error('Hermes confirmed none of the ' + meta.length +
    ' item(s) in this batch — nothing was marked as sent. ' +
    String(r.return_description || r.message || r.return_value || '').slice(0, 300));
}

return out;
